INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a7f8dab1-f5f2-4cd5-aed2-6bd4d8588f66', 'c3c3c3c3-3030-4000-8000-000000000003', 4, 'Dia 4 — Respirar', 'Semana 1: Parar', '{"pch": "Soprou nas suas narinas o f\u00f4lego de vida\u2026 A respira\u00e7\u00e3o \u00e9 o primeiro presente de Deus.", "verse": "Gn 2,7", "lectio": "Leia Gn 2,4-7. Deus formou e soprou.", "practice": "Pratique 5 minutos de respira\u00e7\u00e3o consciente: 4s inspira, 7s segura, 8s expira.", "question": "Quando foi a \u00faltima vez que voc\u00ea respirou com consci\u00eancia?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;